lee_difference.source:
board = [obs['c' + str(index)] for index in range(16)]
actions = ['up', 'left', 'right', 'down']
edges = {'left': [0, 4, 8, 12], 'right': [3, 7, 11, 15], 'up': [0, 1, 2, 3], 'down': [12, 13, 14, 15]}
best = -1000000
for direction in actions:
    if obs['valid_' + direction]:
        score = sum(1 for index in edges[direction] if board[index] == 0) * 2
        score -= actions.index(direction)
        if score > best:
            best = score
            action = direction

